"""Independent review: observed JdbcTemplate override in top-level vs member class."""
import hashlib
import importlib.util
import json
from pathlib import Path
import shutil
import sys

sys.dont_write_bytecode = True
ROOT = Path('/Users/zel/projects/mana')
OUT = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('resource_cli', ROOT / 'scripts/mana-resource-timeline.py')
cli = importlib.util.module_from_spec(spec)
spec.loader.exec_module(cli)
override = '''class CustomJdbc extends JdbcTemplate {
    @Override public void execute(String sql) { throw new IllegalStateException("custom override"); }
}'''
variants = {
    'standard': '',
    'top-level': '\n' + override + '''
@Configuration class CustomConfig {
    @Bean public CustomJdbc customJdbc() { return new CustomJdbc(); }
}
''',
    'member-class': '''
@Configuration class CustomConfig {
    static ''' + override + '''
    @Bean public CustomJdbc customJdbc() { return new CustomJdbc(); }
}
''',
}
results = []
for name, extra in variants.items():
    project = OUT / ('dispatch-' + name)
    shutil.copytree(ROOT / 'tests/fixtures/resource-timeline', project)
    path = project / 'src/main/java/fixture/Resources.java'
    path.write_text(path.read_text().replace('public void sequence()', '@Transactional public void sequence()') + extra)
    context = json.loads((project / 'context.json').read_text())
    context['resourceLeafPolicy'] = 'JDBC_LITERAL_V1'
    (project / 'context.json').write_text(json.dumps(context))
    before = {str(p.relative_to(project)): hashlib.sha256(p.read_bytes()).hexdigest() for p in project.rglob('*') if p.is_file()}
    report = cli.analyze(project, project / 'context.json', 'fixture.Operations#sequence()')
    after = {str(p.relative_to(project)): hashlib.sha256(p.read_bytes()).hexdigest() for p in project.rglob('*') if p.is_file()}
    assert before == after
    leaves = [e for e in report['transactionModel']['events'] if e['kind'] == 'RESOURCE_LEAF_CALL']
    expected = 2 if name == 'standard' else 0
    facts = report['sourceFacts']
    row = {'case': name, 'expectedLeaves': expected, 'actualLeaves': len(leaves),
           'verdict': 'PASS' if len(leaves) == expected else 'FAIL',
           'physicalIds': [o['transactionContext']['physicalId'] for o in report['observations']],
           'placement': [o['placement']['status'] for o in report['observations']],
           'sourceUnchangedDuringAnalysis': True,
           'sourceSha256': hashlib.sha256(path.read_bytes()).hexdigest(),
           'classes': [{'name': c['name'], 'parents': c['parents'], 'methods': [{'name': m['name'], 'returnType': m['returnType']} for m in c['methods']]} for c in facts['classes']]}
    (OUT / (name + '-report.json')).write_text(json.dumps(report, indent=2) + '\n')
    results.append(row)
(OUT / 'nested-dispatch-results.json').write_text(json.dumps(results, indent=2) + '\n')
print(json.dumps(results, indent=2))
sys.exit(1 if any(r['verdict'] == 'FAIL' for r in results) else 0)
